"use client";
import * as React from "react";
import { RadioGroup as BaseRadioGroup } from "@base-ui-components/react/radio-group";
import { Radio as BaseRadio } from "@base-ui-components/react/radio";
import { cn } from "@/lib/utils";

// shadcn-style RadioGroup on the Base UI primitives. Colors are theme tokens only.
export function RadioGroup({ className, ...props }: React.ComponentProps<typeof BaseRadioGroup>) {
  return <BaseRadioGroup className={cn("flex flex-col gap-2", className)} {...props} />;
}

export function Radio({ className, ...props }: React.ComponentProps<typeof BaseRadio.Root>) {
  return (
    <BaseRadio.Root
      className={cn(
        "flex h-4 w-4 shrink-0 items-center justify-center rounded-full border border-border bg-background",
        "transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand",
        "data-[checked]:border-brand data-[checked]:bg-brand",
        "disabled:cursor-not-allowed disabled:opacity-50",
        className
      )}
      {...props}
    >
      <BaseRadio.Indicator className="h-1.5 w-1.5 rounded-full bg-brand-foreground" />
    </BaseRadio.Root>
  );
}
